from pathlib import Path
import json,html,hashlib,re
OUT=Path(__file__).resolve().parent;ROOT=OUT.parent.parent
d=json.loads((OUT/'opportunities.json').read_text()); sources=json.loads((OUT/'sources.json').read_text())
e=html.escape
def stamp(t):return f'{int(t)//60}:{t%60:04.1f}' if t%1 else f'{int(t)//60}:{int(t)%60:02}'
def card(r):
 src=f'clips/{r["id"]}.mp4'
 return f'''<article id="{r['id']}" class="opportunity"><div class="cardtop"><span class="badge">{e(r['priority'])} · {r['id']}</span><span>{e(r['lesson'])} · {stamp(r['start'])}–{stamp(r['end'])}</span></div><h3>{e(r['title'])}</h3><div class="comparison"><div><figure><a href="{r['image']}"><img loading="lazy" src="{r['image']}" alt="Current video frame from {e(r['lesson'])} at {stamp(r['image_time'])}"></a><figcaption>Current frame · {stamp(r['image_time'])}</figcaption></figure><p><strong>What’s there:</strong> {e(r['current'])}</p><details class="clip"><summary>Watch current moment + context</summary><video controls playsinline preload="metadata" src="{src}" poster="{r['image']}" style="width:100%;margin-top:12px"></video><p class="small">Existing video excerpt, including three seconds of context on either side. Player time starts at the beginning of the excerpt.</p><a href="{src}">Open excerpt separately</a></details><p class="small"><a href="{r['sequence']}">Inspect frame sequence</a></p></div><div><h4>Proposed illustration</h4><p>{e(r['proposal'])}</p><ol class="beats">{''.join('<li>'+e(b)+'</li>' for b in r['beats'])}</ol><p><strong>Learning benefit:</strong> {e(r['benefit'])}</p><p class="criterion"><strong>Keep it only if:</strong> {e(r['success'])}</p></div></div><details><summary>Narration and proposed treatment</summary><blockquote>{e(r['cue'])}</blockquote><p>{e(r['treatment'])}</p><p><strong>Course boards:</strong> {e(r['board'])}</p></details></article>'''
rows=''.join(f'<tr><td>{e(r["title"])}</td><td>{e(r["decision"])}</td><td>{e(r["reason"])}</td></tr>' for r in d['lessons'])
evidence=[]
for r in sources:
 slug=r['slug'];sheets=sorted((OUT/slug).glob('sheet-*.jpg'));links=' · '.join(f'<a href="{p.relative_to(OUT)}">Sheet {i+1}</a>' for i,p in enumerate(sheets))
 evidence.append(f'<li><strong>{e(next(x["title"] for x in d["lessons"] if x["slug"]==slug))}</strong> · {stamp(r["duration"])}<br>{links} · <a href="transcripts/{slug}.txt">Fresh transcript</a> · <a href="{slug}/source.json">Source record</a></li>')
text=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Start Smarter — Illustration Opportunities</title><style>
:root{{color-scheme:light;--ink:#25283a;--muted:#5a6070;--purple:#584292;--line:#dce0e8}}*{{box-sizing:border-box}}body{{margin:0;background:#f6f7fa;color:var(--ink);font:17px/1.6 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}}main{{max-width:1180px;margin:auto;padding:44px 28px 80px}}header{{max-width:900px;margin-bottom:32px}}.eyebrow{{font-size:13px;text-transform:uppercase;letter-spacing:.13em;color:var(--purple);font-weight:700}}h1{{font-size:42px;line-height:1.15;letter-spacing:-.025em;margin:12px 0 20px}}h2{{font-size:28px;line-height:1.25;margin:44px 0 16px}}h3{{font-size:25px;line-height:1.25;margin:16px 0 22px}}h4{{font-size:18px;margin:0 0 8px}}p{{margin:0 0 16px}}a{{color:#483476;text-underline-offset:3px}}nav{{display:flex;flex-wrap:wrap;gap:12px 24px;margin-top:24px}}.note{{padding:16px 20px;background:#ebe8f3;border-radius:10px;font-size:15px}}.reference{{display:grid;grid-template-columns:1fr 1fr;gap:26px;align-items:center;background:white;padding:24px;border:1px solid var(--line);border-radius:14px}}figure{{margin:0}}img{{display:block;width:100%;height:auto;border-radius:8px}}figcaption,.small{{font-size:13px;color:var(--muted);margin-top:8px}}.opportunity{{background:white;border:1px solid var(--line);border-radius:14px;padding:26px;margin:22px 0;scroll-margin-top:20px}}.cardtop{{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:12px;font-size:14px;color:var(--muted)}}.badge{{background:#ede9f6;color:#49347d;border-radius:20px;padding:5px 12px;font-weight:600}}.comparison{{display:grid;grid-template-columns:1fr 1fr;gap:28px}}.comparison p{{font-size:16px}}.comparison figure{{margin-bottom:16px}}.beats{{display:flex;gap:18px;padding:14px 14px 14px 32px;background:#f3f5f8;border-radius:8px;font-size:14px}}.beats li{{flex:1;padding-left:2px}}.criterion{{border-left:3px solid #76629f;padding-left:14px}}button{{font:inherit;font-size:14px;cursor:pointer;padding:10px 16px;border-radius:7px;background:#443567;color:#fff;border:0}}button:hover{{background:#5b4589}}details{{border-top:1px solid var(--line);margin-top:20px;padding-top:14px;font-size:15px}}summary{{cursor:pointer;font-weight:600}}blockquote{{margin:16px 0;padding:10px 18px;border-left:3px solid #b4a3d1;background:#f8f6fc}}table{{border-collapse:collapse;width:100%;background:white;font-size:15px}}th,td{{padding:16px;border:1px solid var(--line);text-align:left;vertical-align:top}}th{{background:#eeedf5}}td:first-child{{width:18%;font-weight:600}}td:nth-child(2){{width:20%}}.evidence li{{margin:0 0 15px}}dialog{{border:0;border-radius:14px;max-width:1000px;width:94vw;padding:22px;color:var(--ink)}}dialog::backdrop{{background:#10121acc}}dialog video{{width:100%;max-height:70vh;background:#111}}.modalhead{{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:16px}}.modalhead h3{{margin:0;font-size:20px}}footer{{font-size:14px;color:var(--muted);margin-top:32px}}@media(max-width:760px){{main{{padding:26px 16px 50px}}h1{{font-size:32px}}.reference,.comparison{{grid-template-columns:1fr}}.opportunity{{padding:18px}}.beats{{display:block}}.beats li{{margin-bottom:6px}}table,tbody,tr,td{{display:block}}thead{{display:none}}td:first-child,td:nth-child(2){{width:auto}}tr{{margin-bottom:16px}}}}@media print{{button,nav,dialog{{display:none}}body{{background:white;font-size:12px}}.opportunity{{break-inside:avoid}}main{{padding:0}}details{{display:block}}}}
</style></head><body><main><header><div class="eyebrow">Video illustration review · October 7, 2026</div><h1>Start Smarter: show the action that makes the idea click.</h1><p>{e(d['recommendation'])}</p><div class="note"><strong>Review basis:</strong> current video frames and fresh timestamped transcripts. Continuous playback with audible narration has not been performed. These are illustration proposals, with provisional edit windows; no videos have been changed.</div><nav aria-label="Report sections"><a href="#pilot">Three pilot moments</a><a href="#optional">Optional ideas</a><a href="#coverage">All seven videos</a><a href="#evidence">Evidence & scope</a></nav></header>
<section class="reference"><figure><img src="why-learn-ai/detail/170.jpg" alt="Why Learn AI current frame: student revising a garden project with feedback"><figcaption>Style reference · Why Learn AI? · 2:50</figcaption></figure><div><div class="eyebrow">The reference to carry forward</div><h3>Student + specific action + visible work.</h3><p>Photographic realism, believable teenagers, ordinary clothing, natural lighting, and a clear teaching subject. Preserve that maturity and clarity while choosing the visual form for each concept.</p><p>A phone interaction needs readable changing screen states. A student scene needs the work itself in view. Effective existing diagrams and animations stay.</p><p class="small">Reference also supported by the installed club-app scenes in In Your Hands. Generated illustration concepts in this report have not yet been produced.</p></div></section>
<section id="pilot"><h2>The pilot: three moments, two videos</h2><p>P1 and P2 address the clearest missing examples. P3 tests a short practical takeaway using the same student and setting as P1. This keeps the first batch small and makes its effect easy to compare.</p>{''.join(card(r) for r in d['opportunities'][:3])}</section>
<section id="optional"><h2>Two ideas to hold in reserve</h2><p>These passages already have useful visuals. Revisit them only if the pilot demonstrates a clear benefit.</p>{''.join(card(r) for r in d['opportunities'][3:])}</section>
<section id="coverage"><h2>Decision for every video</h2><p>No illustration quota. Five videos remain unchanged in the recommended first batch.</p><table><thead><tr><th>Lesson</th><th>Decision</th><th>Reason and useful visuals to preserve</th></tr></thead><tbody>{rows}</tbody></table></section>
<section><h2>Production brief for the pilot</h2><p>Create a shared student/desk scene for P1 and P3, plus a separate phone close-up for P2. Generate photographic assets from the saved Why Learn AI? references; render exact screen text, quiz states, and keyboard interactions separately so they remain legible and controlled.</p><p>Build short before/after excerpts with the existing narration. Preserve audio, duration, course-board wording, and the standard closes. Readable action takes priority over camera movement. Choose final cut frames against the actual narration, including the diagram return in P2 and the board-to-close transition in P3.</p><p>Review the encoded excerpts at 720p with sound: does the image teach the named action, is it clear before the narration moves on, and does it retain the value of the existing sequence? Drop any addition that merely makes the video look busier. Whole-video verification and shipping follow after the selected edits are built.</p></section>
<section id="evidence"><h2>Evidence and scope</h2><p>{e(d['scope'])}</p><p>{e(d['method'])}</p><p>The source selection uses the current working copy of index.html, including its existing local edits. Source-file hashes and decoded frame counts are recorded; each full sequential decode matched its reported frame count. The Video Tracker was not accessed, and no tracker or public-deployment status is inferred.</p><ul class="evidence">{''.join(evidence)}</ul><p><a href="opportunities.json">Structured proposal</a> · <a href="sources.json">All source hashes</a> · <a href="lesson-context.txt">Current page teaching context</a> · <a href="../../scripts/video/EDIT-SPEC.md">Video edit standards</a> · <a href="../beyond-the-average-current-spec-review-2026-09-29/NOTEBOOK-GRAPHICS-REASSESSMENT.md">Prior Beyond the New Average scene reassessment</a></p></section><footer>This is an illustration-opportunity review, not a fresh narration verdict or ship approval. All course videos, lesson assets, and existing work remain unchanged.</footer></main></body></html>'''
(OUT/'review.html').write_text(text)
# Keep current authoritative teaching text readily inspectable, excluding lesson activities.
page=(ROOT/'index.html').read_text(); snippets=[]
for name in ['WhyDeeperSection','LLMsSection','AIHistorySection','DoesAIThinkSection','ControlSection','WhyBotherSection','StudyingWithAISection']:
 block=page.split('function '+name+'(',1)[1].split('\nfunction ',1)[0]
 begin=block.find('return ');block=block[begin:]; finish=block.find('closeBoard(');block=block[:finish] if finish>=0 else block
 lines=[]
 for line in block.splitlines():
  if any(x in line for x in ['style:', 'className:', 'key:', 'useState','onClick:']):continue
  strings=re.findall(r'"((?:[^"\\]|\\.)*)"',line)
  for raw in strings:
   try: val=json.loads('"'+raw+'"')
   except Exception: val=raw
   if len(val)>25:lines.append(val)
 snippets.append(name+'\n'+'\n'.join(lines))
(OUT/'lesson-context.txt').write_text('Current index.html teaching context, extracted 2026-10-07.\nindex.html SHA-256: '+hashlib.sha256(page.encode()).hexdigest()+'\n\n'+'\n\n'.join(snippets))
# Confirm all local report links resolve and inputs remained unchanged.
paths=re.findall(r'(?:src|href)="([^"#]+)"',text)
missing=[p for p in paths if not (OUT/p.split('#')[0]).exists()]
assert not missing,missing
for r in sources:assert hashlib.sha256(Path(r['source']).read_bytes()).hexdigest()==r['sha256'],r['slug']
checks={'local_links_resolve':True,'video_hashes_unchanged':True,'videos':len(sources),'total_duration_seconds':sum(r['duration'] for r in sources),'sampled_frames':sum(int(r['duration']//6)+1 for r in sources),'full_decode_counts_match':all(r['frames']==r['decoded_frames'] for r in sources),'continuous_audiovisual_review':False}
(OUT/'review-checks.json').write_text(json.dumps(checks,indent=2));print(json.dumps(checks))
